<script setup lang="ts">
import {Button} from '@openclaw-plugins/control-ui-kit';
import {taskTime} from '../timing.mjs';
import {statusLabels,time,deliveryLabels,type TaskSummary,type TaskRecord} from './models';
import Information from './Information.vue';
import MessageText from './MessageText.vue';
const props=defineProps<{title:string;tasks:TaskSummary[];empty:string;records:TaskRecord[];collapsed:Set<string>;now:number;redact:(value:string)=>string}>();
const emit=defineEmits<{toggle:[task:TaskSummary];navigate:[view:string];original:[record:TaskRecord]}>();
const safe=(value:unknown)=>props.redact(String(value??''));
const recordFor=(task:TaskSummary)=>props.records.find(r=>r.jobId===task.jobId);
const expanded=(task:TaskSummary)=>!!recordFor(task)&&!props.collapsed.has(task.jobId);
function fields(record:TaskRecord):[string,unknown][]{return [['任务标识',safe(record.jobId)],['执行模型',safe(record.model?(record.harness??'codex')+' / '+record.model:'旧任务未记录模型')],['任务队列',safe(record.queueId??record.taskClass??'short')],['Hermes 模板',safe(record.hermesTemplateId??'旧执行配置')],['用时',taskTime(record,props.now)],['受理时间',time(record.createdAt)],['开始时间',time(record.startedAt)],['结束时间',time(record.finishedAt)],[record.notificationKind==='context_request'?'提问投递':'结果交付',deliveryLabels[record.notificationState??'']??record.notificationState??'无异步交付记录']];}
function diagnosticFields(record:TaskRecord):[string,unknown][]{const d=record.collaboration;if(!d)return [];return [['插件请求额度',d.requests.plugin.used+' / '+d.requests.plugin.limit],['信息追问额度',d.requests.context.used+' / '+d.requests.context.limit],['事件投递尝试',String(d.delivery.attempts)],['下次重试',time(d.delivery.retryAt)],['最近失败代码',safe(d.delivery.lastErrorCode??'无记录')],['等待时长',d.waiting?Math.floor(d.waiting.ageMs/1000)+' 秒':'未等待'],['会话最近通知的技能版本',safe(d.skill.lastNotifiedRevision??'未记录')],['实际读取技能','未知；更新通知不代表已读取'],['投递说明',safe(d.delivery.meaning)],['诊断采集时间',time(d.observedAt)]];}
</script>
<template>
 <section class="cq-task-list"><h3>{{title}}</h3><p v-if="!tasks.length" class="cq-muted">{{empty}}</p><article v-for="task in tasks" :key="task.jobId" class="cq-task-card" :class="{'cq-task-selected':expanded(task)}" :data-record-key="task.jobId"><Button class="cq-task-entry ocp:whitespace-normal" variant="ghost" :aria-expanded="expanded(task)" :title="expanded(task)?undefined:safe(task.task??'查看任务详情')" @click="emit('toggle',task)"><div class="cq-task-heading"><time>{{time(task.createdAt)}}</time><span class="cq-elapsed">{{taskTime(task,now)}}</span><span class="cq-state" :class="task.status">{{statusLabels[task.status]??task.status}}</span></div><p v-if="!expanded(task)" class="cq-task-goal">{{safe(task.task??'任务摘要未保存，点击查看详情')}}</p></Button>
 <template v-for="record in expanded(task)?[recordFor(task)!]:[]" :key="record.jobId"><div class="cq-task-details"><template v-if="record.request.availability==='available'"><MessageText :text="safe(record.request.task)"/><details v-if="record.request.context" class="cq-disclosure"><summary>任务上下文</summary><MessageText class="cq-disclosure-body" :text="safe(record.request.context)"/></details><details v-if="record.request.constraints" class="cq-disclosure"><summary>执行限制</summary><MessageText class="cq-disclosure-body" :text="safe(record.request.constraints)"/></details></template><p v-else class="cq-muted">{{safe(task.task??'原始任务正文不可用，旧任务不会补造任务内容。')}}</p><Information :fields="fields(record)"/><details v-if="record.collaboration" class="cq-disclosure"><summary>Main–Worker 协作诊断</summary><Information class="cq-disclosure-body" :fields="diagnosticFields(record)"/></details><details v-if="record.progress" class="cq-disclosure"><summary>当前进度</summary><p class="cq-disclosure-body">{{safe(record.progress)}}</p></details><p v-if="record.error" class="cq-error">{{safe(record.error)}}</p><div class="cq-task-links"><Button variant="ghost" @click="emit('navigate','records')">查看对话</Button><Button variant="ghost" @click="emit('navigate','process')">查看执行过程</Button><Button variant="ghost" class="cq-original-button" @click="emit('original',record)">原始任务 JSON</Button></div></div></template>
 </article></section>
</template>
